def geo(src,which='national'):
    if which=='temple':return [dict(scope='city',stateCodes=['KL'],localityIds=['thiruvananthapuram'],basis='institution-location',note='Public temple in Thiruvananthapuram; no privately owned property parcel or residence is pinned.',sourceIds=src)]
    if which=='delhi':return [dict(scope='state',stateCodes=['DL'],localityIds=[],basis='headquarters',note='Issuer registered-office association in the cited filing, not the location of every newsroom, subscriber or transaction.',sourceIds=src)]
    if which=='foreign':return [dict(scope='unknown',stateCodes=[],localityIds=[],basis='unknown',note='Foreign institution or person; no India money-transfer destination or private address is inferred.',sourceIds=src)]
    return [dict(scope='national',stateCodes=[],localityIds=[],basis='national-context',note='India public-interest context; no project-level delivery, payment destination or residence is established.',sourceIds=src)]
def dims(src,dom,lay,where='national'):
    return dict(domains=dom,layers=lay,geography=geo(src,where),route='/follow-the-money',sourceIds=src,limitations=[])
def ent(id,label,type,src,dom,summary,identity,where='national',canonical=None):
    x=dict(id=id,label=label,type=type,resolved=True,identityBasis=identity,summary=summary,**dims(src,dom,['people' if type=='person' else 'organisations'],where))
    if canonical:x['canonicalId']=canonical
    S['entities'].append(x)
def amount(value,currency,unit,stage,period):return dict(value=value,currency=currency,unit=unit,stage=stage,period=period)
def edge(id,fr,to,kind,label,summary,src,dom,case,date,end=None,tier='documented',response=(),amounts=(),where='national',alternatives=(),falsifier='A superseding original instrument or reconciled ledger contradicting this stated relationship would require correction.',status='source-retained'):
    S['relationships'].append(dict(id=id,fromDate=date,toDate=end or date,**{'from':fr,'to':to},kind=kind,label=label,summary=summary,tier=tier,status=status,statusAsOf=end or date,dateBasis='Exact dated source or transaction dates; no open-ended continuity inferred.',alternativeExplanations=list(alternatives),falsifier=falsifier,responseIds=list(response),recordIds=[case],amounts=list(amounts),**dims(src,dom,['funding'] if amounts else ['people'] if kind=='role' else ['legal'] if 'audit' in kind else ['organisations'],where)))
def rec(id,title,summary,src,dom,entities,rels,date,end,response,alternatives,falsifier,kind='investigation-case',tier='documented',status='reviewed-with-stated-gaps',amounts=(),where='national',limitations=()):
    x=dict(id=id,title=title,summary=summary,kind=kind,tier=tier,status=status,statusAsOf=end,fromDate=date,toDate=end,dateBasis='Dated source and event window; earlier context and historical accounting period are labelled separately.',entityIds=entities,relationshipIds=rels,period=date+' to '+end,response=response,alternativeExplanations=alternatives,falsifier=falsifier,amounts=list(amounts),**dims(src,dom,['funding','legal','organisations'],where));x['limitations']=list(limitations);S['records'].append(x)

