# Normalize prose spacing introduced by compact authoring without altering identifiers or URLs.
import re
def readable(v):
    if isinstance(v,list):return [readable(x) for x in v]
    if isinstance(v,dict):return {k:(x if k in {'id','url','sourceIds','entityIds','relationshipIds','responseIds','recordIds','from','to','canonicalId','localityIds','fromDate','toDate','statusAsOf','publishedAt','retrievedAt','route'} else readable(x)) for k,x in v.items()}
    if isinstance(v,str):
        v=re.sub(r'([a-zA-Z%])(?=\d)',r'\1 ',v)
        v=re.sub(r'(?<=\d)(?=[A-Z])',' ',v)
        v=re.sub(r',(?=[A-Za-z])',', ',v)
        v=re.sub(r'(?<=[a-z])(?=[A-Z])',' ',v)
        v=re.sub(r'(?<=\d),(?=(?:19|20)\d{2}\b)',', ',v)
        v=re.sub(r'\bL (\d{5}) (DL|GJ) (\d{4}) PLC (\d{6})',r'L\1\2\3PLC\4',v)
        v=re.sub(r'\bEFTA (\d+)',r'EFTA\1',v)
        for token in ['IPI','ICM','Puri','Epstein','Hoffman','CBI','SEBI','RRPR','INR','USD','MA1465','October','September','August','July','June','May','April','January','November','December','FY2025']:
            v=re.sub(r'(?<=[a-z])'+token,r' '+token,v)
        return v
    return v
